def solve_grid(grid):
    h, w = len(grid), len(grid[0])

    # Make a copy
    result = [[grid[i][j] for j in range(w)] for i in range(h)]

    def get_component(i, j):
        val = grid[i][j]
        visited = set()
        stack = [(i,j)]

        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                    stack.append((nr,nc))

        return visited

    # Find single-cell components and replace them
    single_cells = []
    for i in range(h):
        for j in range(w):
            comp = get_component(i, j)
            if len(comp) == 1:
                single_cells.append((i, j))

    # For each single cell, replace with most common 8-neighbor
    for i, j in single_cells:
        neighbors = []
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w:
                    neighbors.append(result[ni][nj])

        from collections import Counter
        counts = Counter(neighbors)
        # Most common - break ties by picking largest value? Or first encountered?
        # Let's try most common, break tie by preferring larger value
        if counts:
            max_count = max(counts.values())
            candidates = [v for v, c in counts.items() if c == max_count]
            result[i][j] = max(candidates)  # Prefer larger value on tie

    return result

