def solve_grid_v2(grid, min_component_size=5):
    h, w = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(w)] for i in range(h)]

    def get_component(i, j):
        val = grid[i][j]
        visited = set()
        stack = [(i,j)]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                    stack.append((nr,nc))
        return visited

    # Find all single-cell components
    single_cells = []
    for i in range(h):
        for j in range(w):
            comp = get_component(i, j)
            if len(comp) == 1:
                single_cells.append((i, j))

    # For each single cell, find valid replacement candidates
    for i, j in single_cells:
        neighbors = []
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w:
                    # Only count neighbors that are part of large components
                    neighbor_comp_size = get_component_size(result, ni, nj)
                    if neighbor_comp_size >= min_component_size:
                        neighbors.append((result[ni][nj], (ni,nj)))

        from collections import Counter
        counts = Counter([v for v, _ in neighbors])
        if counts:
            max_count = max(counts.values())
            candidates = [v for v, c in counts.items() if c == max_count]
            result[i][j] = max(candidates)  # Prefer larger value on tie
        else:
            # Fallback: just pick any neighbor
            neighbors_all = [(result[ni][nj], (ni,nj)) 
                           for di in [-1, 0, 1] for dj in [-1, 0, 1]
                           if (di*dj) != 0 
                           and 0 <= i+di < h and 0 <= j+dj < w]
            result[i][j] = neighbors_all[0][0]

    return result

