def solve_grid_v3(grid):
    """Replace single-cell components with their LARGEST-REGION neighbor"""
    h, w = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(w)] for i in range(h)]

    def get_component(i, j):
        val = grid[i][j]
        visited = set()
        stack = [(i,j)]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                    stack.append((nr,nc))
        return visited

    # First, find all component sizes upfront
    comp_sizes = {}
    for i in range(h):
        for j in range(w):
            if (i,j) not in comp_sizes:
                comp = get_component(i, j)
                for (r,c) in comp:
                    comp_sizes[(r,c)] = len(comp)

    # Now process single cells
    single_cells = []
    for i in range(h):
        for j in range(w):
            if comp_sizes.get((i,j), 0) == 1:
                single_cells.append((i, j))

    for i, j in single_cells:
        # Get neighbor colors and their largest connected component sizes
        candidates = []
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w:
                    neighbors_color = result[ni][nj]
                    largest_size_for_this_color = max(
                        comp_sizes.get((r,c), 0) 
                        for r in [ni-1, ni, ni+1] for c in [nj-1, nj, nj+1]
                        if comp_sizes.get((r,c), 0) > 0
                    )
                    candidates.append((neighbors_color, largest_size_for_this_color, (ni,nj)))

        if candidates:
            # Pick the candidate whose color forms the largest region
            # If tie, pick the first one (or largest value as tiebreaker?)
            sorted_cands = sorted(candidates, key=lambda x: (-x[1], -x[0]))
            best = sorted_cands[0]
            result[i][j] = best[0]

    return result

