def solve_grid_v4(grid):
    """Replace single-cell components, preferring neighbors in certain directions"""
    h, w = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(w)] for i in range(h)]

    def get_component(i, j):
        val = grid[i][j]
        visited = set()
        stack = [(i,j)]
        while stack:
            r, c = stack.pop()
            if (r,c) in visited:
                continue
            visited.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                    stack.append((nr,nc))
        return visited

    # Precompute component sizes
    comp_sizes = {}
    for i in range(h):
        for j in range(w):
            if (i,j) not in comp_sizes:
                comp = get_component(i, j)
                for (r,c) in comp:
                    comp_sizes[(r,c)] = len(comp)

    single_cells = []
    for i in range(h):
        for j in range(w):
            if comp_sizes.get((i,j), 0) == 1:
                single_cells.append((i, j))

    for i, j in single_cells:
        # Count neighbors by direction
        dir_counts = {'N': Counter(), 'E': Counter(), 'S': Counter(), 'W': Counter()}
        for di, dj in [(-1,0), (0,1), (1,0), (0,-1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < h and 0 <= nj < w:
                color = result[ni][nj]
                key = ('N','E','S','W')[('N','E','S','W').index(('N'if di==-1 else 'S') or ('E' if dj==1 else 'W'))]
                dir_counts[key][color] += 1

        # Get most common per direction
        most_common = {}
        for key, cnt in dir_counts.items():
            most_common[key] = cnt.most_common(1)[0][0] if cnt else None

        # Pick the most common among N and W (upper/left preference?)
        cand_colors = [v for k,v in [('N',most_common['N']),('E',most_common['E']),('S',most_common['S']),('W',most_common['W'])] 
                      if v is not None]

        if cand_colors:
            # Try picking max color value as tiebreaker (or first encountered)
            result[i][j] = max(cand_colors)

    return result

